// GetRule gets an individual rule
func (s *Store) GetRule(ctx context.Context, id string) (*flipt.Rule, error) {
	var (
		createdAt timestamp
		updatedAt timestamp

		rule = &flipt.Rule{}

		err = s.builder.Select("id, flag_key, segment_key, \"rank\", created_at, updated_at").
			From("rules").
			Where(sq.And{sq.Eq{"id": id}}).
			QueryRowContext(ctx).
