		for key, item := range v { m[fmt.Sprint(key)] = convert(item) }
		return m
	case map[string]interface{}:
		m := make(map[string]interface{}, len(v))
		for key, item := range v { m[key] = convert(item) }
		return m
	case []interface{}:
		items := make([]interface{}, len(v))
		for i, item := range v { items[i] = convert(item) }
		return items
	default:
		return value
	}
