		for _, c := range s.Constraints {
			if c == nil { return fmt.Errorf("nil constraint in segment %q", s.Key) }
			comparison, ok := flipt.ComparisonType_value[c.Type]
			if !ok { return fmt.Errorf("unknown comparison type %q", c.Type) }
			if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{SegmentKey: s.Key, Type: flipt.ComparisonType(comparison), Property: c.Property, Operator: c.Operator, Value: c.Value}); err != nil { return fmt.Errorf("create constraint in segment %q: %w", s.Key, err) }
		}
