	for _, f := range doc.Flags {
		if f == nil { return fmt.Errorf("nil flag") }
		if _, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled}); err != nil { return fmt.Errorf("create flag %q: %w", f.Key, err) }
		variantIDs := make(map[string]string, len(f.Variants))
		for _, v := range f.Variants {
			if v == nil { return fmt.Errorf("nil variant in flag %q", f.Key) }
			attachment := ""
			if v.Attachment != nil {
				value := convert(v.Attachment)
				// Existing documents may contain an attachment as a JSON string.
				if raw, ok := value.(string); ok && json.Valid([]byte(raw)) {
